import{_ as a,c as l,al as t,o as i}from"./chunks/framework.D3pXwl8O.js";const f=JSON.parse('{"title":"Statistical Flight Log Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"en/dev_log/flight_log_analysis_statistical.md","filePath":"en/dev_log/flight_log_analysis_statistical.md"}'),s={name:"en/dev_log/flight_log_analysis_statistical.md"};function o(r,e,n,g,h,c){return i(),l("div",null,e[0]||(e[0]=[t('<h1 id="statistical-flight-log-analysis" tabindex="-1">Statistical Flight Log Analysis <a class="header-anchor" href="#statistical-flight-log-analysis" aria-label="Permalink to &quot;Statistical Flight Log Analysis&quot;">​</a></h1><p>This topic contains information and resources related to statistical flight log analysis.</p><h2 id="flight-review-public-logs" tabindex="-1">Flight Review Public Logs <a class="header-anchor" href="#flight-review-public-logs" aria-label="Permalink to &quot;Flight Review Public Logs&quot;">​</a></h2><p><a href="./../log/flight_log_analysis.html#flight-review-online-tool">Flight Review</a> hosts a large set of publicly available log files that can be used for statistical analysis, machine learning, or other purposes.</p><p>The dataset contains a set of different:</p><ul><li>vehicle types</li><li>PX4 versions (including development versions)</li><li>boards</li><li>flight modes</li></ul><p>The logs are accessible on <a href="https://logs.px4.io/browse" target="_blank" rel="noreferrer">logs.px4.io/browse</a> and are licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC-BY PX4</a>.</p><p>Log files can also be downloaded in bulk with the <a href="https://github.com/PX4/flight_review/blob/main/app/download_logs.py" target="_blank" rel="noreferrer">download_logs.py</a> script. The script allows to filter by different attributes (like flight modes, airframe name or type). Use the <code>--help</code> flag for a full list. The newest logs will be downloaded first, and downloads can be interrupted and resumed later on.</p><p>There are different parsing libraries, for example <a href="./../log/flight_log_analysis.html#pyulog">pyulog</a> can be used to read logs with Python.</p>',9)]))}const p=a(s,[["render",o]]);export{f as __pageData,p as default};
